(function(seed){
  const c = new City(seed, 80);
  c.disastersEnabled = false;
  c.funds = 9e9;                                          // unlimited construction budget
  // 4 coal plants along the top. The nominal slot is 8 + 18k; if that slot is
  // water or otherwise unbuildable on this seed, scan RIGHT deterministically
  // for the first slot that takes one, so every corpus seed really gets 4
  // plants (an unscreened seed with 0 plants measures nothing but darkness).
  for (let k = 0; k < 4; k++) {
    if (c.place("coal", 8 + k * 18, 2).ok) continue;
    for (let x = 4; x <= 73; x++) if (c.place("coal", x, 2).ok) break;
  }
  for (let x = 4; x <= 75; x++) c.place("wire", x, 4);          // bus row, orthogonally touching the 2x2 plants
  const SP = [7, 26, 44, 62];                                   // wire-spine columns
  // WATER AND CIVICS FIRST. place() refuses an occupied tile, so every water
  // and service tile has to claim its ground BEFORE the zoning sweep. The
  // first edition of this script placed them AFTER it: the tower, the pipe
  // run, the school and the hospital were all silent no-ops, waterSupply
  // stayed 0, every lot was capped by WATER_CAP, and the reference city came
  // out 100% level 1 (measured lvlHist {0:1316, 1:1100}, wateredTiles 0) - so
  // the baseline every later milestone compares against never exercised the
  // level-2/3 building art, the density ladder or the water gate at all.
  // Mains run as ROWS on a 5 pitch, UPPER HALF ONLY. recomputeWater stamps
  // (WATER_REACH - d) * 40 with WATER_REACH 3, so d = 3 stamps a literal zero
  // and a lot must sit within TWO tiles of a main: a 5 pitch covers rows 4..43
  // exactly and the lower half stays deliberately dry, so the baseline
  // exercises BOTH sides of the density gate. Rows, not columns, because a
  // column would sever the horizontal conduction that carries power from the
  // spines across each zone row (measured: vertical mains left the reference
  // city at 263 developed lots instead of ~1,100 - dark, not dry).
  // Towers are placed FIRST inside each main row: each one seeds the flood for
  // the pipe segments either side of it, and every segment cut by a spine gap
  // still has a tower. 40 towers = 6,000 units of supply.
  for (let y = 6; y <= 41; y += 5) {
    for (const tx of [5, 12, 35, 53, 70]) c.place("watertower", tx, y);
    for (let x = 4; x <= 75; x++) if (SP.indexOf(x) < 0) c.place("pipe", x, y);
  }
  // Service coverage over the WATERED half only, on a pitch that clears both
  // the spine columns and the tower columns. SVC_CAP wants eduCov or medCov
  // >= 8 and stampCoverage gives (14 - d) * 18 at full funding, so this opens
  // the level-3 gate across the upper half while the dry lower half stays
  // capped - the baseline then covers all three density tiers at once.
  for (const sx of [13, 37, 57]) { c.place("school", sx, 13); c.place("hospital", sx, 33); }
  for (let y = 9; y <= 39; y += 6) for (let x = 9; x <= 73; x += 6) c.place("park", x, y);
  for (let y = 8; y <= 74; y += 3) for (let x = 4; x <= 75; x++) c.place("road", x, y);
  for (const wx of SP) for (let y = 4; y <= 75; y++) c.place("wire", wx, y); // spines (cross roads -> WIREROAD)
  for (let y = 6; y <= 75; y++) for (let x = 4; x <= 75; x++) {
    const band = (y < 30) ? "zr" : (y < 52) ? "zc" : "zi";
    c.place(band, x, y);
  }
  c.funds = 200000;                                        // real starting funds at t=0
  c.powerDirty = true;
  return c;
})
